"use client";

import { Input } from "@base-ui/react/input";
import {
  ArrowLeftIcon,
  FolderKanbanIcon,
  PencilIcon,
  PlusIcon,
  SearchIcon,
  ShieldCheckIcon,
  ShieldOffIcon,
  UserRoundIcon,
} from "lucide-react";

import { Link } from "@/components/link";
import { CustomerForm } from "@/components/plugins/customers/customer-form";
import { customerLabels } from "@/components/plugins/customers/labels";
import type {
  CustomerDetailPageProps,
  CustomerNewPageProps,
  CustomerSection,
  CustomersPageProps,
} from "@/components/plugins/customers/types";
import {
  buttonClass,
  cardClass,
  CustomerActionButton,
  CustomerAvatar,
  DeleteCustomer,
  iconButtonClass,
  inputClass,
  primaryButtonClass,
} from "@/components/plugins/customers/ui";
import { customerDisplayName } from "@/components/plugins/customers/utils";
import { cn } from "@/components/utils/cn";
import {
  tableActionCellClass,
  tableCellClass,
  tableClass,
  tableHeaderClass,
  tablePanelClass,
  tableRowClass,
} from "@/components/utils/table-styles";

export type {
  Customer,
  CustomerFormValues,
  CustomerCreateValues,
  CustomerSection,
  CustomersPageProps,
  CustomerDetailPageProps,
  CustomerNewPageProps,
} from "@/components/plugins/customers/types";
export type { CustomersLabels } from "@/components/plugins/customers/labels";

const pageClass = "mx-auto w-full min-w-0 space-y-6 px-4 py-8 text-foreground";

export function CustomersPage({
  customers,
  search,
  onSearchChange,
  loading = false,
  error,
  createHref,
  getCustomerHref,
  onDelete,
  onSetVerified,
  onImpersonate,
  toolbar,
  syncColumn,
  className,
  labels: overrides,
  linkComponent: CustomerLink = Link,
}: CustomersPageProps) {
  const labels = { ...customerLabels, ...overrides };
  return (
    <div className={cn(pageClass, className)}>
      <section className={cn(tablePanelClass, "space-y-5")} aria-label={labels.title}>
        <header className="flex flex-wrap items-center justify-between gap-3">
          <div className="space-y-1.5">
            <h1 className="text-base font-semibold">{labels.title}</h1>
            <p className="text-sm text-muted-foreground">{labels.description}</p>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {toolbar}
            <CustomerLink href={createHref} className={primaryButtonClass}>
              <PlusIcon aria-hidden="true" />
              {labels.create}
            </CustomerLink>
          </div>
        </header>
        <div className="relative max-w-sm">
          <SearchIcon
            aria-hidden="true"
            className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground"
          />
          <Input
            aria-label={labels.search}
            placeholder={labels.searchPlaceholder}
            value={search}
            onChange={(event) => onSearchChange(event.target.value)}
            className={cn(inputClass, "pl-9")}
          />
        </div>
        {error ? (
          <p role="alert" className="text-sm text-red-600 dark:text-red-400">
            {error}
          </p>
        ) : loading ? (
          <output className="block py-10 text-center text-sm text-muted-foreground">
            {labels.loading}
          </output>
        ) : (
          <div className="overflow-x-auto">
            <table className={tableClass}>
              <thead>
                <tr className={tableRowClass}>
                  {[
                    labels.customer,
                    labels.email,
                    ...(syncColumn ? [syncColumn.label] : []),
                    labels.actions,
                  ].map((label, index) => (
                    <th
                      scope="col"
                      key={index}
                      className={
                        index === (syncColumn ? 3 : 2) ? tableActionCellClass : tableHeaderClass
                      }
                    >
                      {label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="[&_tr:last-child]:border-0">
                {customers.map((customer) => (
                  <tr key={customer.id} className={tableRowClass}>
                    <td className={tableCellClass}>
                      <div className="flex items-center gap-3">
                        <CustomerAvatar customer={customer} />
                        <div className="flex flex-wrap items-baseline gap-x-2">
                          <span className="font-medium">{customerDisplayName(customer)}</span>
                          {customer.companyName?.trim() && (
                            <span className="text-xs text-muted-foreground">{customer.name}</span>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className={tableCellClass}>
                      <div className="flex items-center gap-1">
                        <span>{customer.email}</span>
                        {onSetVerified ? (
                          <CustomerActionButton
                            label={customer.emailVerified ? labels.unverify : labels.verify}
                            labels={labels}
                            onAction={() => onSetVerified(customer.id, !customer.emailVerified)}
                          >
                            {customer.emailVerified ? (
                              <ShieldOffIcon aria-hidden="true" />
                            ) : (
                              <ShieldCheckIcon aria-hidden="true" />
                            )}
                          </CustomerActionButton>
                        ) : (
                          <span className="text-xs text-muted-foreground">
                            {customer.emailVerified ? labels.verified : labels.unverified}
                          </span>
                        )}
                      </div>
                    </td>
                    {syncColumn && (
                      <td className={tableCellClass}>{syncColumn.render(customer)}</td>
                    )}
                    <td className={tableActionCellClass}>
                      <div className="flex items-start justify-end gap-1">
                        {onImpersonate && (
                          <CustomerActionButton
                            label={labels.impersonate}
                            labels={labels}
                            onAction={() => onImpersonate(customer.id)}
                          >
                            <UserRoundIcon aria-hidden="true" />
                          </CustomerActionButton>
                        )}
                        <CustomerLink
                          href={getCustomerHref(customer, "projects")}
                          className={iconButtonClass}
                          aria-label={labels.viewProjects}
                        >
                          <FolderKanbanIcon aria-hidden="true" />
                        </CustomerLink>
                        <CustomerLink
                          href={getCustomerHref(customer, "about")}
                          className={iconButtonClass}
                          aria-label={labels.edit}
                        >
                          <PencilIcon aria-hidden="true" />
                        </CustomerLink>
                        {onDelete && (
                          <DeleteCustomer customer={customer} onDelete={onDelete} labels={labels} />
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
                {customers.length === 0 && (
                  <tr className={tableRowClass}>
                    <td
                      colSpan={syncColumn ? 4 : 3}
                      className={cn(tableCellClass, "py-10 text-center text-muted-foreground")}
                    >
                      {labels.empty}
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  );
}

export function CustomerDetailPage({
  customer,
  section = "about",
  backHref,
  sectionHrefs,
  onSave,
  onDelete,
  emailChangeDescription,
  projectsContent,
  syncContent,
  className,
  labels: overrides,
  linkComponent: CustomerLink = Link,
}: CustomerDetailPageProps) {
  const labels = { ...customerLabels, ...overrides };
  return (
    <div className={cn(pageClass, className)}>
      <CustomerLink href={backHref} className={buttonClass}>
        <ArrowLeftIcon aria-hidden="true" />
        {labels.back}
      </CustomerLink>
      <header className={cn(cardClass, "flex flex-wrap items-center gap-4")}>
        <div className="flex min-w-0 items-center gap-4">
          <CustomerAvatar customer={customer} large />
          <div className="min-w-0">
            <h1 className="truncate text-base font-semibold">{customerDisplayName(customer)}</h1>
            <p className="truncate text-sm text-muted-foreground">{customer.email}</p>
          </div>
        </div>
        <dl className="ml-auto flex flex-wrap gap-x-6 gap-y-2 text-sm">
          <div>
            <dt className="text-muted-foreground">{labels.email}</dt>
            <dd className="font-medium">
              {customer.emailVerified ? labels.verified : labels.unverified}
            </dd>
          </div>
          {customer.banned && (
            <div>
              <dt className="text-muted-foreground">{labels.banned}</dt>
              <dd className="font-medium text-red-600 dark:text-red-400">{labels.yes}</dd>
            </div>
          )}
        </dl>
      </header>
      <nav aria-label={labels.sections} className="flex overflow-x-auto border-b border-border">
        {(["about", "projects", "sync"] as const).map((tab: CustomerSection) => (
          <CustomerLink
            key={tab}
            href={sectionHrefs[tab]}
            aria-current={section === tab ? "page" : undefined}
            className={cn(
              "shrink-0 border-b-2 border-transparent px-4 py-2 text-sm font-semibold text-muted-foreground hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-inset",
              section === tab && "border-primary text-primary",
            )}
          >
            {labels[tab]}
          </CustomerLink>
        ))}
      </nav>
      {section === "about" ? (
        <>
          <CustomerForm
            key={customer.id}
            customer={customer}
            labels={labels}
            onSubmit={onSave}
            emailChangeDescription={emailChangeDescription}
          />
          {onDelete && (
            <DeleteCustomer
              key={customer.id}
              customer={customer}
              labels={labels}
              onDelete={onDelete}
            />
          )}
        </>
      ) : section === "projects" ? (
        projectsContent
      ) : (
        syncContent
      )}
    </div>
  );
}

export function CustomerNewPage({
  backHref,
  onCreate,
  passwordMinLength,
  passwordMaxLength,
  className,
  labels: overrides,
  linkComponent: CustomerLink = Link,
}: CustomerNewPageProps) {
  const labels = { ...customerLabels, ...overrides };
  return (
    <div className={cn(pageClass, className)}>
      <CustomerLink href={backHref} className={buttonClass}>
        <ArrowLeftIcon aria-hidden="true" />
        {labels.back}
      </CustomerLink>
      <header className={cn(cardClass, "space-y-1.5")}>
        <h1 className="text-base font-semibold">{labels.newTitle}</h1>
        <p className="text-sm text-muted-foreground">{labels.newDescription}</p>
      </header>
      <CustomerForm
        labels={labels}
        onSubmit={onCreate}
        passwordMinLength={passwordMinLength}
        passwordMaxLength={passwordMaxLength}
      />
    </div>
  );
}

"use client";

import { Input } from "@base-ui/react/input";
import { CopyIcon, DicesIcon } from "lucide-react";
import { useId, useState, type FormEvent } from "react";

import type { CustomersLabels } from "@/components/plugins/customers/labels";
import type {
  Customer,
  CustomerCreateValues,
  CustomerFormValues,
} from "@/components/plugins/customers/types";
import {
  buttonClass,
  cardClass,
  Feedback,
  inputClass,
  primaryButtonClass,
  useCustomerAction,
} from "@/components/plugins/customers/ui";
import { customerFormValues, generateCustomerPassword } from "@/components/plugins/customers/utils";
import { cn } from "@/components/utils/cn";

export interface CustomerFormProps {
  customer?: Customer;
  labels: CustomersLabels;
  onSubmit: (values: CustomerCreateValues) => Promise<void>;
  emailChangeDescription?: string;
  passwordMinLength?: number;
  passwordMaxLength?: number;
}

export function CustomerForm({
  customer,
  labels,
  onSubmit,
  emailChangeDescription,
  passwordMinLength = 12,
  passwordMaxLength = 128,
}: CustomerFormProps) {
  const id = useId();
  const creating = !customer;
  const [values, setValues] = useState(() => customerFormValues(customer));
  const [password, setPassword] = useState("");
  const [errors, setErrors] = useState<Partial<Record<keyof CustomerCreateValues, string>>>({});
  const [passwordFeedback, setPasswordFeedback] = useState<{ error: boolean; message: string }>();
  const action = useCustomerAction(labels.actionError);

  async function copyPassword(value: string) {
    try {
      await navigator.clipboard.writeText(value);
      setPasswordFeedback({ error: false, message: labels.passwordCopied });
    } catch {
      setPasswordFeedback({ error: true, message: labels.passwordCopyError });
    }
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (action.pending) return;
    const form = event.currentTarget;
    const nextErrors: typeof errors = {};
    if (!values.name.trim()) nextErrors.name = labels.nameRequired;
    const emailInput = form.elements.namedItem("email") as HTMLInputElement;
    if (((!creating || password) && !values.email.trim()) || emailInput.validity.typeMismatch)
      nextErrors.email = labels.emailRequired;
    if (
      creating &&
      password &&
      (password.length < passwordMinLength || password.length > passwordMaxLength)
    )
      nextErrors.password = labels.passwordInvalid(passwordMinLength, passwordMaxLength);
    setErrors(nextErrors);
    const firstInvalid = Object.keys(nextErrors)[0];
    if (firstInvalid) {
      (form.elements.namedItem(firstInvalid) as HTMLInputElement)?.focus();
      return;
    }
    const normalized: CustomerFormValues = {
      ...values,
      name: values.name.trim(),
      email: values.email.trim(),
    };
    const data = creating && password ? { ...normalized, password } : normalized;
    if (await action.run(() => onSubmit(data), creating ? labels.created : labels.saved)) {
      setValues(normalized);
      setPassword("");
      setPasswordFeedback(undefined);
    }
  }

  function field(
    name: keyof CustomerFormValues,
    options: {
      type?: string;
      autoComplete?: string;
      placeholder?: string;
      required?: boolean;
      full?: boolean;
      description?: string;
    } = {},
  ) {
    const error = errors[name];
    const descriptionId = `${id}-${name}-description`;
    const errorId = `${id}-${name}-error`;
    return (
      <div className={cn("space-y-2", options.full && "md:col-span-2")}>
        <label htmlFor={`${id}-${name}`} className="block text-sm font-semibold">
          {labels[name]}
          {options.required && " *"}
        </label>
        <Input
          id={`${id}-${name}`}
          name={name}
          type={options.type ?? "text"}
          autoComplete={options.autoComplete}
          placeholder={options.placeholder}
          required={options.required}
          value={values[name]}
          onChange={(event) => {
            setValues({ ...values, [name]: event.target.value });
            setErrors({ ...errors, [name]: undefined });
          }}
          className={inputClass}
          aria-invalid={Boolean(error)}
          aria-describedby={
            [options.description ? descriptionId : "", error ? errorId : ""]
              .filter(Boolean)
              .join(" ") || undefined
          }
        />
        {options.description && (
          <p id={descriptionId} className="text-sm text-muted-foreground">
            {options.description}
          </p>
        )}
        {error && (
          <p id={errorId} role="alert" className="text-sm text-red-600 dark:text-red-400">
            {error}
          </p>
        )}
      </div>
    );
  }

  return (
    <form noValidate onSubmit={submit} aria-busy={action.pending} className="space-y-6">
      <fieldset disabled={action.pending} className="min-w-0 space-y-6">
        <section aria-labelledby={`${id}-contact`} className={cn(cardClass, "space-y-5")}>
          <div className="space-y-1.5">
            <h2 id={`${id}-contact`} className="font-semibold">
              {labels.contactTitle}
            </h2>
            <p className="text-sm text-muted-foreground">{labels.contactDescription}</p>
          </div>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            {field("name", { required: true, autoComplete: "name" })}
            {field("email", {
              type: "email",
              autoComplete: "email",
              required: !creating || Boolean(password),
              description: creating ? undefined : emailChangeDescription,
            })}
            {creating && (
              <div className="space-y-2">
                <label htmlFor={`${id}-password`} className="block text-sm font-semibold">
                  {labels.password}
                </label>
                <div className="relative">
                  <Input
                    id={`${id}-password`}
                    name="password"
                    type="password"
                    autoComplete="new-password"
                    value={password}
                    minLength={passwordMinLength}
                    maxLength={passwordMaxLength}
                    onChange={(event) => {
                      setPassword(event.target.value);
                      setErrors({ ...errors, password: undefined });
                      setPasswordFeedback(undefined);
                    }}
                    className={cn(inputClass, "pl-20")}
                    aria-invalid={Boolean(errors.password)}
                    aria-describedby={`${id}-password-description${errors.password ? ` ${id}-password-error` : ""}`}
                  />
                  <div className="absolute inset-y-0 left-1 flex items-center">
                    <button
                      type="button"
                      className={cn(buttonClass, "px-2")}
                      aria-label={labels.generatePassword}
                      onClick={() => {
                        try {
                          const generated = generateCustomerPassword(
                            passwordMinLength,
                            passwordMaxLength,
                          );
                          setPassword(generated);
                          setErrors({ ...errors, password: undefined });
                          void copyPassword(generated);
                        } catch {
                          setPasswordFeedback({
                            error: true,
                            message: labels.passwordGenerateError,
                          });
                        }
                      }}
                    >
                      <DicesIcon aria-hidden="true" />
                    </button>
                    <button
                      type="button"
                      className={cn(buttonClass, "px-2")}
                      disabled={!password}
                      aria-label={labels.copyPassword}
                      onClick={() => void copyPassword(password)}
                    >
                      <CopyIcon aria-hidden="true" />
                    </button>
                  </div>
                </div>
                <p id={`${id}-password-description`} className="text-sm text-muted-foreground">
                  {labels.passwordDescription(passwordMinLength, passwordMaxLength)}
                </p>
                {errors.password && (
                  <p
                    id={`${id}-password-error`}
                    role="alert"
                    className="text-sm text-red-600 dark:text-red-400"
                  >
                    {errors.password}
                  </p>
                )}
                <Feedback feedback={passwordFeedback} />
              </div>
            )}
            {field("phoneNumber", {
              type: "tel",
              autoComplete: "tel",
              placeholder: labels.phonePlaceholder,
            })}
          </div>
        </section>
        <section aria-labelledby={`${id}-company`} className={cn(cardClass, "space-y-5")}>
          <div className="space-y-1.5">
            <h2 id={`${id}-company`} className="font-semibold">
              {labels.companyTitle}
            </h2>
            <p className="text-sm text-muted-foreground">{labels.companyDescription}</p>
          </div>
          {field("companyName", { autoComplete: "organization" })}
        </section>
        <section aria-labelledby={`${id}-billing`} className={cn(cardClass, "space-y-5")}>
          <h2 id={`${id}-billing`} className="font-semibold">
            {labels.billingTitle}
          </h2>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            {field("street", {
              full: true,
              autoComplete: "address-line1",
              placeholder: labels.streetPlaceholder,
            })}
            {field("city", { autoComplete: "address-level2", placeholder: labels.cityPlaceholder })}
            {field("addressComplement", {
              autoComplete: "address-line2",
              placeholder: labels.addressPlaceholder,
            })}
          </div>
        </section>
        <div className="flex justify-end">
          <button type="submit" className={primaryButtonClass}>
            {action.pending ? labels.pending : creating ? labels.create : labels.save}
          </button>
        </div>
      </fieldset>
      <Feedback feedback={action.feedback} />
    </form>
  );
}

import type { ComponentType, ReactNode } from "react";

import type { LinkProps } from "@/components/link";
import type { CustomersLabels } from "@/components/plugins/customers/labels";

export type CustomerSection = "about" | "projects" | "sync";

export interface CustomerFormValues {
  name: string;
  email: string;
  phoneNumber: string;
  companyName: string;
  street: string;
  city: string;
  addressComplement: string;
}

export interface CustomerCreateValues extends CustomerFormValues {
  password?: string;
}

export interface Customer extends Pick<CustomerFormValues, "name" | "email"> {
  id: string;
  emailVerified: boolean;
  image?: string | null;
  banned?: boolean | null;
  companyName?: string | null;
  phoneNumber?: string | null;
  street?: string | null;
  city?: string | null;
  addressComplement?: string | null;
}

export interface CustomersAppearanceProps {
  className?: string;
  labels?: Partial<CustomersLabels>;
  linkComponent?: ComponentType<LinkProps>;
}

export interface CustomersPageProps extends CustomersAppearanceProps {
  customers: readonly Customer[];
  search: string;
  onSearchChange: (search: string) => void;
  loading?: boolean;
  error?: string;
  createHref: string;
  getCustomerHref: (customer: Customer, section: CustomerSection) => string;
  onDelete?: (customerId: string) => Promise<void>;
  onSetVerified?: (customerId: string, verified: boolean) => Promise<void>;
  onImpersonate?: (customerId: string) => Promise<void>;
  toolbar?: ReactNode;
  syncColumn?: { label: string; render: (customer: Customer) => ReactNode };
}

export interface CustomerDetailPageProps extends CustomersAppearanceProps {
  customer: Customer;
  section?: CustomerSection;
  backHref: string;
  sectionHrefs: Record<CustomerSection, string>;
  onSave: (values: CustomerFormValues) => Promise<void>;
  onDelete?: (customerId: string) => Promise<void>;
  emailChangeDescription?: string;
  projectsContent?: ReactNode;
  syncContent?: ReactNode;
}

export interface CustomerNewPageProps extends CustomersAppearanceProps {
  backHref: string;
  onCreate: (values: CustomerCreateValues) => Promise<void>;
  passwordMinLength?: number;
  passwordMaxLength?: number;
}

"use client";

import { Avatar } from "@base-ui/react/avatar";
import { Dialog } from "@base-ui/react/dialog";
import { Trash2Icon } from "lucide-react";
import { useRef, useState, type ReactNode } from "react";

import type { CustomersLabels } from "@/components/plugins/customers/labels";
import type { Customer } from "@/components/plugins/customers/types";
import { customerDisplayName, customerInitials } from "@/components/plugins/customers/utils";
import { cn } from "@/components/utils/cn";

export const cardClass = "rounded-3xl border border-border bg-background p-5 text-foreground";
export const buttonClass =
  "inline-flex min-h-9 shrink-0 items-center justify-center gap-2 rounded-lg px-3 text-sm font-medium text-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4";
export const primaryButtonClass = cn(
  buttonClass,
  "bg-primary text-primary-foreground hover:bg-primary/90 hover:text-primary-foreground",
);
export const outlineButtonClass = cn(buttonClass, "border border-border");
export const iconButtonClass = cn(buttonClass, "size-8 min-h-8 p-0");
export const inputClass =
  "h-8 w-full min-w-0 rounded-2xl border border-input bg-muted px-3 text-base text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50 aria-invalid:ring-2 aria-invalid:ring-red-600 md:text-sm";

export function useCustomerAction(errorMessage: string) {
  const lock = useRef(false);
  const [pending, setPending] = useState(false);
  const [feedback, setFeedback] = useState<{ error: boolean; message: string }>();
  async function run(action: () => Promise<void>, success: string) {
    if (lock.current) return false;
    lock.current = true;
    setPending(true);
    setFeedback(undefined);
    try {
      await action();
      setFeedback({ error: false, message: success });
      return true;
    } catch {
      setFeedback({ error: true, message: errorMessage });
      return false;
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return { pending, feedback, run };
}

export function Feedback({ feedback }: { feedback?: { error: boolean; message: string } }) {
  return feedback ? (
    <p
      role={feedback.error ? "alert" : "status"}
      className={cn(
        "text-sm",
        feedback.error ? "text-red-600 dark:text-red-400" : "text-muted-foreground",
      )}
    >
      {feedback.message}
    </p>
  ) : null;
}

export function CustomerAvatar({
  customer,
  large = false,
}: {
  customer: Customer;
  large?: boolean;
}) {
  const name = customerDisplayName(customer);
  return (
    <Avatar.Root
      className={cn(
        "flex size-9 shrink-0 items-center justify-center overflow-hidden rounded-full border border-border",
        large && "size-16 text-xl",
      )}
    >
      <Avatar.Image
        src={customer.image ?? undefined}
        alt={name}
        className="size-full object-cover"
      />
      <Avatar.Fallback>{customerInitials(name, customer.email)}</Avatar.Fallback>
    </Avatar.Root>
  );
}

export function CustomerActionButton({
  label,
  onAction,
  labels,
  children,
}: {
  label: string;
  onAction: () => Promise<void>;
  labels: CustomersLabels;
  children: ReactNode;
}) {
  const action = useCustomerAction(labels.actionError);
  return (
    <div>
      <button
        type="button"
        className={iconButtonClass}
        aria-label={label}
        disabled={action.pending}
        aria-busy={action.pending}
        onClick={() => void action.run(onAction, labels.actionSuccess)}
      >
        {children}
      </button>
      <Feedback feedback={action.feedback} />
    </div>
  );
}

export function DeleteCustomer({
  customer,
  onDelete,
  labels,
}: {
  customer: Customer;
  onDelete: (id: string) => Promise<void>;
  labels: CustomersLabels;
}) {
  const [open, setOpen] = useState(false);
  const action = useCustomerAction(labels.actionError);
  return (
    <div>
      <Dialog.Root
        open={open}
        onOpenChange={(next) => {
          if (!action.pending) setOpen(next);
        }}
      >
        <Dialog.Trigger
          className={cn(iconButtonClass, "text-destructive hover:text-destructive")}
          aria-label={labels.deleteCustomer}
          disabled={action.pending}
        >
          <Trash2Icon aria-hidden="true" />
        </Dialog.Trigger>
        <Dialog.Portal>
          <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
          <Dialog.Popup
            className={cn(
              cardClass,
              "fixed top-1/2 left-1/2 z-50 w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 space-y-5 shadow-xl",
            )}
          >
            <Dialog.Title className="text-lg font-semibold">{labels.deleteCustomer}</Dialog.Title>
            <Dialog.Description className="text-sm text-muted-foreground">
              {labels.deleteDescription(customerDisplayName(customer))}
            </Dialog.Description>
            <Feedback feedback={action.feedback} />
            <div className="flex justify-end gap-2">
              <Dialog.Close className={outlineButtonClass} disabled={action.pending}>
                {labels.cancel}
              </Dialog.Close>
              <button
                type="button"
                disabled={action.pending}
                className={cn(
                  buttonClass,
                  "bg-destructive text-destructive-foreground hover:bg-destructive/90 hover:text-destructive-foreground",
                )}
                onClick={async () => {
                  if (await action.run(() => onDelete(customer.id), labels.deleted)) setOpen(false);
                }}
              >
                {action.pending ? labels.pending : labels.confirmDelete}
              </button>
            </div>
          </Dialog.Popup>
        </Dialog.Portal>
      </Dialog.Root>
      {!open && <Feedback feedback={action.feedback} />}
    </div>
  );
}

import type { Customer, CustomerFormValues } from "@/components/plugins/customers/types";

export function customerDisplayName(customer: Pick<Customer, "name" | "companyName">) {
  return customer.companyName?.trim() || customer.name;
}

export function customerInitials(name: string, email: string) {
  return name.trim()
    ? name
        .trim()
        .split(/\s+/)
        .slice(0, 2)
        .map((part) => part[0])
        .join("")
        .toUpperCase()
    : email.trim().slice(0, 2).toUpperCase() || "?";
}

export function customerFormValues(customer?: Customer): CustomerFormValues {
  return {
    name: customer?.name ?? "",
    email: customer?.email ?? "",
    phoneNumber: customer?.phoneNumber ?? "",
    companyName: customer?.companyName ?? "",
    street: customer?.street ?? "",
    city: customer?.city ?? "",
    addressComplement: customer?.addressComplement ?? "",
  };
}

// Web Crypto is accessed only when the user requests a password.
export function generateCustomerPassword(min = 12, max = 128) {
  if (!Number.isInteger(min) || !Number.isInteger(max) || min < 1 || max < min || max > 1024) {
    throw new RangeError("Password limits must be integers within 1–1024.");
  }
  const groups = [
    "abcdefghijkmnopqrstuvwxyz",
    "ABCDEFGHJKLMNPQRSTUVWXYZ",
    "23456789",
    "!@#$%^&*()-_=+",
  ];
  const alphabet = groups.join("");
  function randomIndex(length: number) {
    const limit = Math.floor(0x1_0000_0000 / length) * length;
    const random = new Uint32Array(1);
    do {
      crypto.getRandomValues(random);
    } while (random[0] >= limit);
    return random[0] % length;
  }
  const length = Math.min(max, Math.max(20, min));
  const characters = groups.slice(0, length).map((group) => group[randomIndex(group.length)]);
  while (characters.length < length) characters.push(alphabet[randomIndex(alphabet.length)]);
  for (let index = characters.length - 1; index > 0; index--) {
    const other = randomIndex(index + 1);
    [characters[index], characters[other]] = [characters[other], characters[index]];
  }
  return characters.join("");
}
